/**
 * docs/spec-coverage.md is generated by `pnpm docs:spec` (scripts/spec-coverage.ts) from the spec
 * links in source comments and in the test files: it goes stale whenever a source or test file
 * gains or loses a spec section link, and this test says so.
 *
 * The URL normalization the index relies on is pinned below, so two spellings of one section never
 * show up as an implemented-but-untested pair.
 */
import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { renderSpecCoverage, sectionOf, SPEC_COVERAGE } from "../../../../scripts/spec-coverage.ts";

describe("spec section URL normalization", () => {
  test("multipage and single-page HTML Standard URLs name the same section", () => {
    const single = sectionOf("https://html.spec.whatwg.org/#the-input-element");
    expect(sectionOf("https://html.spec.whatwg.org/multipage/input.html#the-input-element")).toEqual(single);
    expect(single).toEqual({ spec: "html", anchor: "the-input-element" });
  });

  test("spec levels and TR snapshots collapse onto the editor's draft", () => {
    expect(sectionOf("https://www.w3.org/TR/cssom-1/#dom-cssstylesheet-insertrule")).toEqual({ spec: "css:cssom", anchor: "dom-cssstylesheet-insertrule" });
    expect(sectionOf("https://drafts.csswg.org/cssom/#dom-cssstylesheet-insertrule")).toEqual({ spec: "css:cssom", anchor: "dom-cssstylesheet-insertrule" });
    expect(sectionOf("https://www.w3.org/TR/wai-aria-1.2/#button")).toEqual(sectionOf("https://w3c.github.io/aria/#button"));
  });

  test("links without a fragment, repositories and namespace URIs are not sections", () => {
    expect(sectionOf("https://dom.spec.whatwg.org/")).toBeNull();
    expect(sectionOf("https://github.com/web-platform-tests/wpt/blob/master/dom/nodes/Node-contains.html#L3")).toBeNull();
    expect(sectionOf("http://www.w3.org/1999/xhtml")).toBeNull();
    expect(sectionOf("https://html.spec.whatwg.org/entities.json")).toBeNull();
  });
});

describe("docs/spec-coverage.md", () => {
  test("is generated from the current sources and tests", () => {
    const doc = readFileSync(SPEC_COVERAGE, "utf8");
    expect(renderSpecCoverage() === doc, "docs/spec-coverage.md is stale: run `pnpm docs:spec`").toBe(true);
  });
});
